import type { ErrorBoundaryFallbackProps } from '@suspensive/react';
import { useState } from 'react';
import i18n from '~/shared/i18n/i18n';
import { parseError } from '~/shared/lib/utils/error-message';
import { Dialog } from '~/shared/ui/dialogs/dialog';

type CommonErrorProps = ErrorBoundaryFallbackProps & {
  buttonLabel?: string[];
  onConfirmClick?: () => void;
};

export const ExchangeErrorFallback = ({
  error,
  reset: resetErrorBoundary,
  buttonLabel,
  onConfirmClick,
}: CommonErrorProps) => {
  const [isOpen, setIsOpen] = useState(true);

  let errorMessage = '',
    title = '';

  // validation 에러 메시지 처리
  try {
    errorMessage = (error as any).validationErrors
      ? (error as any).validationErrors[0].message
      : parseError(error).message;
    title = parseError(error).title ?? i18n.t('validation:temporaryErrorOccurred');
  } catch (e) {
    // title = i18n.t('validation:temporaryErrorOccurred');
    errorMessage = i18n.t('validation:verificationTimeExpired');
  }

  const handleCancel = () => {
    try {
      history?.back();
      setTimeout(() => {
        resetErrorBoundary();
      }, 0);
    } catch (e) {
      location.href = '/';
    }
  };

  const handleConfirm = () => {
    onConfirmClick?.();
    resetErrorBoundary();
  };

  return (
    <Dialog
      afterLeave={() => null}
      open={isOpen}
      onClose={() => setIsOpen(false)}
      onConfirmClick={handleConfirm}
      onCancelClick={handleCancel}
      title={title}
      message={errorMessage}
      buttonLabel={buttonLabel}
    />
  );
};
